package com.openggf.game.soniccd.level;
import com.openggf.game.soniccd.*;import com.openggf.game.soniccd.media.*;import com.openggf.game.soniccd.objects.*;
import org.junit.jupiter.api.BeforeAll;import org.junit.jupiter.api.Test;import java.nio.file.*;import java.util.*;
import static org.junit.jupiter.api.Assertions.*;import static org.junit.jupiter.api.Assumptions.assumeTrue;
/** Native/file operands and same-reader cache contracts; allJavaUNRUN. */
class TestCdProgrammeTtDoorSource {
 static CdProgrammeObjectSource source;static CdMmdImage image;
 @BeforeAll static void actual()throws Exception{String root=System.getProperty("soniccd.media.root","");Path cue=Path.of(root,"USA","Sonic CD (US).cue");assumeTrue(!root.isBlank()&&Files.isRegularFile(cue));try(var a=CdProgramAssets.open(cue,Optional.of(CdReleaseVariant.USA),Optional.empty())){source=CdProgrammeData.open(a,CdR4DataLayout.Programme.R41A).objectSource();image=a.mmd(CdNativeFile.R41A);}}
 @Test void actualHex28DispatchAndMappingStoreAuthenticateRootRatherThanLabelText(){assertEquals(0x20CCFEL,source.view(CdProgrammeObjectSource.Table.DISPATCH).bytes().unsignedLong((0x28-1)*4));assertArrayEquals(java.util.HexFormat.of().parseHex("317c44400002117c00020018217c0020cf460004"),source.view(CdProgrammeObjectSource.Table.DOOR_MAP_STORE).bytes().copy());assertEquals(0x20CF46,source.doorData().mapping());}
 @Test void threeAppendedViewsBorrowExactOriginalFileAndCacheSameReaderData(){for(var t:List.of(CdProgrammeObjectSource.Table.DOOR_MAPPINGS,CdProgrammeObjectSource.Table.DOOR_MAP_STORE,CdProgrammeObjectSource.Table.DOOR_SHAPES)){var v=source.view(t);assertSame(v,source.view(t));assertArrayEquals(image.readFile(t.fileOffset(),t.length()),v.bytes().copy());assertEquals(t.sha256(),CdR11aProfile.sha256(v.bytes().copy()));}assertSame(source.doorData(),source.doorData());assertEquals(66,CdProgrammeObjectSource.Table.DOOR_MAPPINGS.ordinal());}
 @Test void completeThreeFrameMappingAndSourceShapeRowsRejectForeignRelation(){for(int n=0;n<3;n++)assertInstanceOf(CdObjectDrawQueue.FrameMapping.class,source.mappings().resolve(0x20CF46,false,n));assertThrows(UnsupportedOperationException.class,()->source.mappings().resolve(0x20CF46,false,3));assertThrows(UnsupportedOperationException.class,()->source.mappings().resolve(0x20CF4C,false,0));int[][] rows={{64,8,128,2},{64,8,128,2},{8,32,64,1},{8,64,128,0},{8,64,128,0}};for(int r=0;r<5;r++)for(int n=0;n<4;n++)assertEquals(rows[r][n],source.doorData().shape(r,n));assertThrows(UnsupportedOperationException.class,()->source.doorData().shape(5,0));}
}
